      "rarity": "rare",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "The superior adamantine-lead alloy known as keep stone is as highly prized as it is expensive, and for good reason: keep stone combines the Hardness and durability of the finest metal with inherent magical protection. Not only does the metal itself resist magical effects, but anyone in proximity to a large amount of it also enjoys a degree of protection from divination magic. Dwarven crafters have attempted to make this extra protection more portable and more affordable in the form of keep stone amulets. Each amulet is unique in its exact shape, size, thickness, and decorations, but typically, a keep stone amulet is roughly palm-sized and engraved with clan symbols, holy aphorisms, or a favorite line of poetry.\nWhile wearing a keep stone amulet, if you're the target of a spell with the detection or scrying trait, the caster must succeed at a check (flat, dc:5, showDC:all) or lose the spell.\nActivate—Rebuff Magic r (concentrate, misfortune)\nFrequency once per day\nTrigger You're the target of a spell with a spell attack roll\nEffect The caster must roll the spell attack roll twice and take the worse result.",
