      "name": "Duty of the Oathsworn",
      "itemType": "equipment",
      "level": 9,
      "rarity": "rare",
      "traits": [
        "contract",
        "invested",
        "magical"
      ],
      "description": "The oath that ties you to your bound dragon transcends the boundaries of life and death. When the pact is made, the dragon chooses one type of creature other than humanoid. (The GM selects the appropriate trait.) You gain resistance equal to half your level to physical and mental damage from these creatures. You also gain the Draconic Precision action. If you die from damage delivered by a creature of this type, you rise as an undead creature of the dragon's choice. This undead's level can be no higher than your level or your bound dragon's, whichever is lower. This undead creature has your mind; if it's normally mindless, it loses that trait and any immunity to mental.\nDraconic Precision 1 (concentrate)\nFrequency once per day\nEffect Your Strikes against the chosen type of enemy deal an additional 1d6 precision damage for 1 minute. This damage increases to 2d6 if you're 17th level or higher.\nOathbreaker's Calamity Should either party break the oath, both you and the dragon are forever forsworn from comradery. Creatures can't treat either of you as an ally while in combat.",
