      "level": 11,
      "rarity": "uncommon",
      "traits": [],
      "description": "This +2 striking longspear was crafted by a renowned monster hunter, who designed the prototype from the bones and scales of a diabolic dragon. The drathyrican folds of a young dragon, the organ that generates their magical breath, are crucial to the operation of the spear. The mechanics of the weapon are largely based on an injection spear: when the safety is disengaged and a secondary lever is squeezed, it produces a magical effect like a dragon's breath from the hollow tip of the spear.\nActivate—Breath of the Spear 2 (concentrate, manipulate)\nEffect The dragon's tongue releases a burst of energy that manifests as a 30-foot type:cone dealing 6d6 untyped damage with a check (reflex, dc:28, basic, options:area-effect) save. You can't use this activation again for 1d4. The damage type matches the breath of the dragon the weapon was made from, and this activation has the corresponding trait.\nCraft Requirements The initial raw materials must include the drathyrican folds of a dragon.",
