      "description": "When a creature enters the snare's square, it is plunged into an unnatural darkness for 1 minute. Light can't enter the square, any non-magical light sources within the square do not emanate any light, and magical light emanating from a spell of rank 2 or below is suppressed. Those outside the area can't see directly into or through the darkness, and all adjacent squares are reduced to dim light.",
