      "description": "These cloaks are created from hand-dyed leather decorated with gemstones, appealing to the individual tastes of the owner. The beautiful decorations of these cloaks encourage their owner to wear them no matter the season, making it visibly part of their unique style. Wearing the cloak boosts self-confidence, granting a +1 item bonus to Diplomacy checks.\nActivate—Overcome Self-Doubt 2 (concentrate, manipulate)\nFrequency once per day\nEffect You readjust your cloak, straightening the collar and brushing out any wrinkles. You gain the effects of a Heroism spell for 1 minute.",
