      "name": "Mariner’s Mien (Lesser)",
      "itemType": "equipment",
      "level": 8,
      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "The swirls on this wooden mask—often worn by Mordant Censors—move and shift, reflecting the shape of the nearest currents. Wearing the mask grants you a +1 item bonus to Sailing Lore and Survival checks. In addition, it allows you to pilot a boat with simply a thought. When you pilot a vehicle, you can keep both hands free and Drive from any location on the vehicle.\nActivate—Set the Course 1 (concentrate)\nFrequency once per day\nRequirements You are aboard a vehicle\nEffect You become Quickened for 1 minute or until you leave the vehicle, whichever comes first, and can use the extra action to Take Control of the vehicle or, if you're already piloting it, Drive or Stop the vehicle.",
      "bulk": 0.1,
