      "name": "Gaze of the Mantis",
      "itemType": "equipment",
      "level": 11,
      "rarity": "rare",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "These glasses have faceted red lenses like those of a mantis and are popular as a less ostentatious alternative to a full mask. While wearing the gaze of the mantis, your field of view increases to give you better awareness of your surroundings. You gain a +2 item bonus to visual Perception checks and cannot be flanked.\nActivate—Target Sense 1\nFrequency once per day\nRequirements You're a Red Mantis assassin\nEffect You learn the distance to and direction of all creatures that have a Red Mantis contract on them within 10 miles. If one of these creatures is within 100 feet, you also know any afflictions, conditions, and spells affecting them. This awareness lasts for 1 hour.",
