      "name": "Crown of the Master (Greater)",
      "itemType": "equipment",
      "level": 13,
      "rarity": "rare",
      "traits": [
        "invested",
        "occult"
      ],
      "description": "This crown, granted to favored azarketis by their alghollthu masters, is made of coral sculpted into the shape of a tentacled creature clutching the wearer's temples. While wearing the crown, you gain a +2 item bonus to saving throws against mental effects and can cast Figment as an occult innate spell.The crown gains the following activation.\nActivate—Imperative Order 2 (concentrate)\nFrequency once per day\nEffect You cast a 6th-rank dominate with a DC of 30. When you cast dominate this way, its duration is reduced to 8 hours.",
