      "description": "The traditional headwear for the Red Mantis assassin is the mask of the mantis. Most of these masks are constructed from hard leather helmets that serve to obscure the assassin's identity and give them the appearance of possessing a mantis's head. Some variants, however, consist only of the mask itself, and are meant to be worn over the face. Regardless of the shape and style, all masks of the mantis function the same.\nMembers of the Vernai can use any mask of the mantis to enhance their frightening presence—something they often do simply to reveal their standing in the society without speaking a word, as detailed fully in the entry for Vernai's Ire activation below.\nWhile wearing a mask of the mantis, you gain a +2 item bonus to Perception checks.\nActivate—Enhance Vision 2 (concentrate, manipulate)\nFrequency once per day\nEffect You cast either a 5th-rank Darkvision or See the Unseen on yourself.\nActivate—Vernai's Ire 1 (concentrate)\nRequirements You are a member of the Vernai\nEffect You cause the mask of the mantis's eyes to shimmer with crimson light, granting yourself a far more harrowing visage. This light creates illumination equivalent to that of a candle. You can use this ability again to extinguish the frightening glow, but as long as Vernai's Ire remains active, you gain a +2 item bonus to Intimidation checks.",
