      "traits": [
        "invested",
        "magical",
        "morph"
      ],
      "description": "These black leather goggle frames have no lenses. Instead, when a actor puts them on and invests them, the wearer's eyes transform and lengthen into snail-like eyestalks. The wobbly eyestalks stretch out through the lens holes and up over the wearer's head on lengthened optic nerves.\nActivate—Looksee 1 (concentrate)\nFrequency once per day\nEffect By focusing hard, you can watch for enemies in all directions. You gain all-around vision for 1 minute; during this time, you can't be flanked.\nEffect: Stalk Goggles",
