      "rarity": "rare",
      "traits": [
        "consumable",
        "light",
        "magical",
        "potion"
      ],
      "description": "Activate 1 (manipulate)\nThis potion's bottle glows softly with shimmering silver light. Upon drinking this potion, you're surrounded by a nimbus of blazing starlight that lasts for 1 minute. You emanate a field of bright light with a 20-foot radius (and dim light for another 20 feet, like a torch). You take a –20 penalty to Stealth checks. Any creature that targets you with an attack or an ability must succeed at a check (fortitude, dc:17) save or be Dazzled for 1 round. A creature who succeeds at this save is immune to the effect for 24 hours.\nEffect: Draft of Stellar Radiance",
