      "description": "This cloak appears to be woven from a thousand living leaves, hungry for flesh and eager to defend the cloak's wearer.\nActivate—Bite Back r (concentrate)\nFrequency once per day\nTrigger You are damaged by a melee attack from an adjacent creature\nEffect The leaves lash out at your attacker, rising up to reveal snapping jaws made of wicked thorns. The triggering creature must attempt a check (reflex, dc:17, options:damaging-effect) saving throw.\nSuccess The creature is unaffected.\nFailure The creature takes 1d4 piercing damage.\nCritical Failure The creature takes 2d4 piercing damage] damage.",
