      "name": "Astrolabe of the Falling Stars",
      "itemType": "equipment",
      "level": 5,
      "rarity": "uncommon",
      "traits": [
        "magical"
      ],
      "description": "This astrolabe is fashioned of magically attuned platinum plates and rings and is inset with carefully measured ruby gems. The astrolabe's back is engraved with helpful charts, a calendar, and a maker's mark.\nAn astrolabe of falling stars can be used as a Mariner's Astrolabe. In addition, it can produce the following magical effect.\nActivate—Starfall 1 (manipulate)\nFrequency once per day\nEffect With a flick of your finger, you set the astrolabe's rule spinning, causing the inset rubies to become a blur. Choose a point within 100 feet. The astrolabe of falling stars calls down a brief rain of meteorites in a 10-foot type:burst centered on that point, dealing 1d8 bludgeoning damage damage to creatures in the area (check (reflex, dc:19, basic) save).\nActivate—Calculate 1 minute (manipulate)\nAstrolabes can be used for navigation in unfamiliar or featureless locations. To use an astrolabe, the holder must be trained in Survival. By spending 1 minute to measure the height of the stars and planets, a holder who knows the time and date can determine the latitude, and a holder who knows their latitude can determine the date and time. An astrolabe also grants a +1 item bonus to checks to identify celestial bodies.",
