      "description": "Activate 1 Strike\nAether marbles create violent, lingering eddies of force that extend partially into unseen planes. You gain a +2 item bonus to attack rolls with the bomb. When the bomb explodes, it deals 3d6 force damage and 3 force splash damage.\nSurfaces in the splash area are filled with twisting eddies of force, which are difficult terrain for incorporeal creatures but not for corporeal ones. The force eddies in a square disperse after an incorporeal creature enters the square.",
