      "rarity": "uncommon",
      "traits": [
        "bulwark",
        "invested",
        "magical"
      ],
      "description": "This +1 resilient full plate is crafted from the most colorful fragments chipped from scales of a dragon turtle's shell, traditionally incorporating that motif in the form of a thicker, sturdier backplate. While wearing this armor, you aren't Off-Guard from creatures that flank you, and you ignore the armor's Speed penalty when you Swim and its check penalty to Athletics checks to Swim.",
