    "sourceHash": "sha256:78264275e805dafd9471563b0416d0983c68b63a3a10060d18e11db768b6d087",
    "translatableHash": "sha256:a9004e9cc45e6492502daef1a09632b42d81beae335dff4092a22ab27b4ad421",
    "data": {
      "schemaVersion": 1,
      "name": "Necrotic Cap (Moderate)",
      "itemType": "consumable",
      "level": 8,
      "rarity": "uncommon",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell (add 1 action)\nYou can use this slimy, rotting mushroom as a spell catalyst when you cast an Acid Grip spell by tapping it against the target, causing the mushroom to release a cloud of necrotic spores. When you do, acid grip loses the acid trait, gains the fungus trait, and all acid damage the spell deals becomes void damage. On a hit, the target additionally gains the Enfeebled 2 and Sickened 2 conditions as the spores consume their flesh. As long as the target is taking persistent void damage, they can't reduce the value of their sickened condition below 1.\nEffect: Necrotic Cap",
      "bulk": 0.1,
      "price": {
        "gp": 80
      },
      "usage": "held-in-one-hand",
      "category": "catalyst",
      "group": "consumable"
    }
