      "description": "This burgundy moss grows in heart-shaped clumps and releases a pleasant, calming scent. The spell DC of any spell cast by Activating this item is 24.\n• Armor You gain resistance 5 to mental damage and a +1 item bonus to saving throws against effects with the emotion trait.\n• Weapon After you cast a healing spell by activating the heartmoss, the weapon exudes a soothing scent. Your Strikes with the affixed weapon have the nonlethal trait for 1 minute. Until the end of your next turn, Strikes with the affixed weapon cause the target to be Stupefied 2 for 1 round if it hits (or for 3 rounds on a critical hit).\nActivate Cast a Spell\nEffect You cast Stabilize.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast 3rd-rank Heal.",
