      "rarity": "uncommon",
      "traits": [
        "magical",
        "spellheart"
      ],
      "description": "This dry clay ball becomes malleable when activated, shifting into a variety of forms. The spell attack roll of any spell cast by Activating this item is 1d20+21 and the spell DC 31.\n• Armor You gain resistance 10 to precision damage and a +3 item bonus to saving throws against effects with the morph or polymorph traits.\n• Weapon After you cast a morph or polymorph spell by activating the clay sphere, the weapon becomes malleable, shifting its form to your whims. Your Strikes with the affixed weapon have the versatile bludgeoning, versatile piercing, and versatile slashing trait for 1 minute. Until the end of your next turn, Strikes with the affixed weapon have their damage dice increase by one step.\nEffect: Clay Sphere - Armor\nEffect: Clay Sphere - Weapon\nActivate Cast a Spell\nEffect You cast Gouging Claw.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Cursed Metamorphosis.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Plant Form.",
