      "description": "Whereas a durian's aroma ranges from pleasant to revolting depending on the person, a durian bomb is a fruit that's been alchemically modified for maximum revulsion. You gain a +1 item bonus to attack rolls.\nOn a successful Strike, a durian bomb deals the 2d4 piercing damage to the target. Any creature hit by the bomb or in its splash area must attempt a check (fortitude, dc:17) saving throw. Creatures in the splash area treat the results of their saving throw as one step better. Creatures sickened by a durian bomb are unable to smell anything else while the sickened condition lasts, suppressing any scent special sense they might have.\nOnce a creature is sickened by a durian bomb, they're immune to the sickened condition caused by other durian bombs for 1 minute.\nCritical Success The target is unaffected.\nSuccess The creature is Sickened 1.\nFailure The creature is Dazzled for 1 round and sickened 1.\nCritical Failure The creature is dazzled for 1 round and Sickened 2.",
