      "description": "Activate 1 Strike\nMade from the acidic flesh of an especially astringent fruit found on the Plane of Wood, this bomb's contents soften, oxidize, and season whatever they touch. You gain a +2 item bonus to attack rolls.\nOn a successful Strike, a tenderizer grenade deals the 3d6 acid damage to the target and the 3 acid splash damage. Any resistances the target has against bludgeoning, piercing, and slashing damage are reduced by an amount based on the bomb's type. In addition, the target is showered with appetizing esters, oils, and salts, making them Off-Guard against jaws Strikes, fangs Strikes, or similar Strikes with a creature's mouth. These additional effects last until the end of your next turn, or for 1 minute on a critical hit.",
