      "description": "This collar is a silken cord from which hangs a small silver amulet that bears the likeness of a woman with her hand at her throat. A gasping lament is a powerful coda instrument that's worn rather than held. While you sing, you gain a +3 item bonus to Intimidation checks to Demoralize and to Performance checks.\nActivate Cast a Spell\nEffect You expend a number of charges from the collar to cast a spell from its list.\n• Cantrip Message\n• 1st Charm, Command\n• 2nd Sonata Span, Ventriloquism\n• 3rd Enthrall, Shatter\n• 4th Honeyed Words, Infectious Melody\n• 5th Command, Concordant Choir\n• 6th Noise Blast, Zealous Conviction\n• 7th Shatter, Vibrant Vibrato\nCraft Requirements Supply one casting of all listed levels of all listed spells.",
