    "data": {
      "schemaVersion": 1,
      "name": "Aurochs' Might Tattoo (Lesser)",
      "itemType": "equipment",
      "level": 8,
      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical",
        "tattoo"
      ],
      "description": "The aurochs depicted by this tattoo is a powerful symbol of strength and resilience. When upgraded, the tattoo expands to depict an increasingly imposing herd of aurochs.\nActivate—Aurochs Charge 2 (concentrate)\nFrequency once per day\nEffect You Stride twice and make a melee Strike against a creature within your reach at any point during your movement. If the Strike hits and deals damage, the target attempts a check (fortitude, dc:24) save to avoid being toppled by the impact.\nCritical Success The target is unaffected.\nSuccess The target is Off-Guard until the beginning of its next turn.\nFailure The target is knocked Prone.\nCritical Failure As failure, but the target also takes 2d6 bludgeoning damage.",
      "bulk": 0,
      "price": {
        "gp": 475
      },
      "usage": "tattooed-on-the-body",
      "category": "equipment",
      "group": "equipment"
    }
