      "level": 5,
      "rarity": "uncommon",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "These heavy gloves are reinforced with thick animal hide and sharpened bone.\nActivate—Shredding Finisher 1 (manipulate)\nFrequency once per hour\nRequirements You hit the same creature with two unarmed Strikes in the same round\nEffect The gauntlets' spikes dig into the creature just before you tear them free, dealing 2d6 piercing damage.",
