      "traits": [
        "extradimensional",
        "magical"
      ],
      "description": "This storage container decorated with images of wildlife and berries is popular among Shoanti quahs and other nomadic groups. The box functions like a spacious pouch, holding 50 Bulk, and is inscribed with magic to keep its contents cool to allow for travel with perishable items like meat and fruit. Items in the box are kept fresh for up to a year.",
