    "sourceHash": "sha256:d4f0c518ff98bf99b70de3fc40e064327d90c06844c791870fbb0f4792b5101d",
    "translatableHash": "sha256:57890bf24b87f0e9455738c6ca4704a6249fca25d595a38b5eed8722b1ffbcaa",
    "data": {
      "schemaVersion": 1,
      "name": "Roc-Shaft Arrow (Moderate)",
      "itemType": "consumable",
      "level": 10,
      "rarity": "uncommon",
      "traits": [
        "consumable",
        "magical"
      ],
      "description": "Ammunition arrow\nActivate 1 Interact\nEach of these arrows is made from an immense roc's flight feather, most of whose vanes have been trimmed to expose the arrow's shaft. When an activated roc-shaft arrow hits a target, the arrow briefly grows a pair of avian wings and attempts to carry off the target. The target must succeed at a check (fortitude, dc:27) save or be moved to a space you choose within 15 feet (20 feet on a critical failure). If this would move the target into a hazardous space, this effect gains the incapacitation trait.",
      "bulk": 0,
      "price": {
        "gp": 160
      },
      "usage": "other",
      "category": "other",
      "group": "consumable"
    }
