      "description": "This +1 striking wounding shortsword has the design of a fanged mouth carved into the handle. Whenever the blade draws blood, it glows with a dull red energy, as if empowered by the taste of blood.\nActivate—Drink Life 2 (concentration)\nFrequency once per hour\nEffect The blood-drinker blade guides your hand to cut a foe and feeds you from their blood. Make a Strike with the blade. On a hit, the attack deals an additional 1d8 persistent bleed damage. You also gain 1d8 temporary Hit Points for 1 minute.\nEffect: Blood-Drinker Blade\nActivate—Exsanguinate 1 (concentrate)\nFrequency once per day\nRequirements Your most recent action was to successfully deal persistent bleed damage to a creature with Drink Life\nEffect The blade's power draws even more blood from your victim. The required creature takes 6d6 persistent bleed damage. You gain temporary Hit Points equal to half the bleed damage the creature takes (after applying resistances and the like). You lose any remaining temporary Hit Points after 1 minute.",
